arguments.content:
resource "google_compute_network" "vpc" {
  name                    = local.vpc_name
  auto_create_subnetworks = false
  labels                  = local.common_labels
}

resource "google_compute_subnetwork" "ingress" {
  name                     = local.ingress_subnet_name
  region                   = var.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = local.ingress_subnet_cidr
  private_ip_google_access = true
  labels                   = local.common_labels
}

resource "google_compute_subnetwork" "private" {
  name                     = local.private_subnet_name
  region                   = var.region
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = local.private_subnet_cidr
  private_ip_google_access = true
  labels                   = local.common_labels
}

resource "google_compute_firewall" "allow_http" {
  name        = "${var.resource_prefix}-allow-http"
  network      = google_compute_network.vpc.id
  description  = "Allow HTTP/8080 ingress to mediapulse ingress and api targets"
  target_tags  = ["mediapulse-ingress", "mediapulse-api"]
  source_tags  = ["mediapulse-ingress"]
  allow {
    protocol = "tcp"
    ports    = ["80", "8080"]
  }
  labels = local.common_labels
}

resource "google_compute_firewall" "allow_db" {
  name        = "${var.resource_prefix}-allow-db"
  network      = google_compute_network.vpc.id
  description  = "Allow TCP 5432 from ingress and private subnets to db targets"
  target_tags  = ["mediapulse-db"]
  source_ranges = [local.ingress_subnet_cidr, local.private_subnet_cidr]
  allow {
    protocol = "tcp"
    ports    = ["5432"]
  }
  labels = local.common_labels
}

# Private Service Access connection for Cloud SQL private IP
resource "google_compute_global_address" "psa" {
  name          = "${var.resource_prefix}-psa-range"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.vpc.id
  labels        = local.common_labels
}

resource "google_service_networking_connection" "psa" {
  network                 = google_compute_network.vpc.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.psa.name]
}

resource "google_kms_key_ring" "main" {
  name     = local.keyring_name
  location = var.region
  labels   = local.common_labels
}

resource "google_kms_crypto_key" "database" {
  name            = local.kms_db_key
  key_ring        = google_kms_key_ring.main.id
  rotation_period = "7776000s"
  labels          = local.common_labels
}

resource "google_kms_crypto_key" "messaging" {
  name            = local.kms_msg_key
  key_ring        = google_kms_key_ring.main.id
  rotation_period = "7776000s"
  labels          = local.common_labels
}

resource "google_kms_crypto_key" "projection" {
  name            = local.kms_proj_key
  key_ring        = google_kms_key_ring.main.id
  rotation_period = "7776000s"
  labels          = local.common_labels
}

resource "google_kms_crypto_key" "audit" {
  name            = local.kms_audit_key
  key_ring        = google_kms_key_ring.main.id
  rotation_period = "7776000s"
  labels          = local.common_labels
}

# Runtime component service accounts
resource "google_service_account" "api" {
  account_id   = local.api_sa
  display_name = "MediaPulse API Cloud Run runtime SA"
  description  = "Least-privilege SA for the MediaPulse Ingest API Cloud Run service"
  labels       = local.common_labels
}

resource "google_service_account" "processor" {
  account_id   = local.proc_sa
  display_name = "MediaPulse Processor function SA"
  labels       = local.common_labels
}

resource "google_service_account" "relay" {
  account_id   = local.relay_sa
  display_name = "MediaPulse Outbox Relay function SA"
  labels        = local.common_labels
}

resource "google_service_account" "archiver" {
  account_id   = local.archiver_sa
  display_name = "MediaPulse Audit Archiver function SA"
  labels       = local.common_labels
}

resource "google_service_account" "scheduler" {
  account_id   = local.sched_sa
  display_name = "MediaPulse Cloud Scheduler invoker SA"
  labels       = local.common_labels
}

# OAuth2 client service accounts for read/write/admin scopes
resource "google_service_account" "client_read" {
  account_id   = local.read_sa
  display_name = "MediaPulse OAuth2 read-scope client"
  labels       = local.common_labels
}

resource "google_service_account" "client_write" {
  account_id   = local.write_sa
  display_name = "MediaPulse OAuth2 write-scope client"
  labels       = local.common_labels
}

resource "google_service_account" "client_admin" {
  account_id   = local.admin_sa
  display_name = "MediaPulse OAuth2 admin-scope client"
  labels       = local.common_labels
}

# User-managed keys serve as OAuth2 client secrets
resource "google_service_account_key" "client_read" {
  service_account_id = google_service_account.client_read.name
  public_key_type    = "TYPE_X509_PEM"
}

resource "google_service_account_key" "client_write" {
  service_account_id = google_service_account.client_write.name
  public_key_type    = "TYPE_X509_PEM"
}

resource "google_service_account_key" "client_admin" {
  service_account_id = google_service_account.client_admin.name
  public_key_type    = "TYPE_X509_PEM"
}

# Identity Platform tenant for scoped JWT auth
resource "google_identity_platform_tenant" "main" {
  provider     = google-beta
  project      = var.project_id
  display_name = "MediaPulse Ingest tenant"
  labels       = local.common_labels
}

# ---- IAM role bindings (least privilege) ----

# API service account
resource "google_project_iam_member" "api_cloudsql_client" {
  project = var.project_id
  role    = "roles/cloudsql.client"
  member  = "serviceAccount:${google_service_account.api.email}"
}

resource "google_project_iam_member" "api_datastore_viewer" {
  project = var.project_id
  role    = "roles/datastore.viewer"
  member  = "serviceAccount:${google_service_account.api.email}"
}

resource "google_project_iam_member" "api_pubsub_publisher" {
  project = var.project_id
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:${google_service_account.api.email}"
}

# Processor service account
resource "google_project_iam_member" "proc_pubsub_subscriber" {
  project = var.project_id
  role    = "roles/pubsub.subscriber"
  member  = "serviceAccount:${google_service_account.processor.email}"
}

resource "google_project_iam_member" "proc_datastore_user" {
  project = var.project_id
  role    = "roles/datastore.user"
  member  = "serviceAccount:${google_service_account.processor.email}"
}

resource "google_cloudfunctions2_function_iam_member" "proc_invoker_pubsub" {
  project       = var.project_id
  location      = var.region
  cloud_function = google_cloudfunctions2_function.processor.name
  role          = "roles/cloudfunctions.invoker"
  member        = "serviceAccount:${google_service_account.processor.email}"
}

# Relay service account
resource "google_project_iam_member" "relay_cloudsql_client" {
  project = var.project_id
  role    = "roles/cloudsql.client"
  member  = "serviceAccount:${google_service_account.relay.email}"
}

resource "google_pubsub_topic_iam_member" "relay_publisher" {
  project = var.project_id
  topic   = google_pubsub_topic.main.name
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:${google_service_account.relay.email}"
}

# Archiver service account
resource "google_project_iam_member" "archiver_cloudsql_client" {
  project = var.project_id
  role    = "roles/cloudsql.client"
  member  = "serviceAccount:${google_service_account.archiver.email}"
}

resource "google_storage_bucket_iam_member" "archiver_object_admin" {
  bucket = google_storage_bucket.audit.name
  role   = "roles/storage.objectAdmin"
  member = "serviceAccount:${google_service_account.archiver.email}"
}

# Scheduler invoker SA -> invoker on relay and archiver functions
resource "google_cloudfunctions2_function_iam_member" "relay_invoker" {
  project        = var.project_id
  location       = var.region
  cloud_function = google_cloudfunctions2_function.relay.name
  role           = "roles/cloudfunctions.invoker"
  member         = "serviceAccount:${google_service_account.scheduler.email}"
}

resource "google_cloudfunctions2_function_iam_member" "archiver_invoker" {
  project        = var.project_id
  location       = var.region
  cloud_function = google_cloudfunctions2_function.archiver.name
  role           = "roles/cloudfunctions.invoker"
  member         = "serviceAccount:${google_service_account.scheduler.email}"
}

# Allow the API service account to read the DB connection secret
resource "google_secret_manager_secret_iam_member" "api_secret_accessor" {
  project   = var.project_id
  secret_id = google_secret_manager_secret.db_url.secret_id
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.api.email}"
}

# KMS encrypter/decrypter for the runtime SAs that use CMEK-backed resources
resource "google_kms_crypto_key_iam_member" "api_kms" {
  crypto_key_id = google_kms_crypto_key.database.id
  role          = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member        = "serviceAccount:${google_service_account.api.email}"
}

resource "google_sql_database_instance" "main" {
  name             = local.sql_instance_name
  database_version = "POSTGRES_16"
  region           = var.region

  settings {
    tier              = "db-f1-micro"
    availability_type = "ZONAL"
    disk_size         = 20
    disk_type         = "PD_SSD"

    ip_configuration {
      ipv4_enabled = false
      private_network = google_compute_network.vpc.id
      require_ssl     = false
    }

    disk_encryption_key {
      kms_key_name = google_kms_crypto_key.database.id
    }

    backup_configuration {
      enabled = true
    }
  }

  depends_on = [google_service_networking_connection.psa]
  labels      = local.common_labels
  deletion_protection = false
}

resource "google_sql_database" "main" {
  name     = var.db_name
  instance = google_sql_database_instance.main.name
}

resource "google_sql_user" "main" {
  name     = var.db_username
  instance = google_sql_database_instance.main.name
  password = var.db_password
}

# DATABASE_URL connection string stored in Secret Manager
locals {
  database_url = "postgresql://${var.db_username}:${var.db_password}@${google_sql_database_instance.main.private_ip_address}:5432/${var.db_name}?sslmode=disable"
}

resource "google_secret_manager_secret" "db_url" {
  secret_id = local.db_secret_name
  labels    = local.common_labels

  replication {
    auto {}
  }
}

resource "google_secret_manager_secret_version" "db_url" {
  secret      = google_secret_manager_secret.db_url.id
  secret_data = local.database_url
}

resource "google_pubsub_topic" "main" {
  name   = local.topic_name
  labels = local.common_labels

  kms_key_name = google_kms_crypto_key.messaging.id
}

resource "google_pubsub_topic" "dlq" {
  name   = local.dlq_topic_name
  labels = local.common_labels
}

resource "google_pubsub_subscription" "processor" {
  name   = local.subscription_name
  topic  = google_pubsub_topic.main.name
  labels = local.common_labels

  push_config {
    push_endpoint = google_cloudfunctions2_function.processor.service_config[0].uri
    oidc_token {
      service_account_email = google_service_account.processor.email
      audience              = google_cloudfunctions2_function.processor.service_config[0].uri
    }
    attributes = {
      x-goog-push-format = "json"
    }
  }

  ack_deadline_seconds = 60

  retry_policy {
    minimum_backoff = "10s"
    maximum_backoff = "600s"
  }

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dlq.id
    max_delivery_attempts = 5
  }

  expiration_policy {
    ttl = ""
  }
}

resource "google_pubsub_subscription" "dlq" {
  name   = local.dlq_sub_name
  topic  = google_pubsub_topic.dlq.name
  labels = local.common_labels

  ack_deadline_seconds = 60

  expiration_policy {
    ttl = ""
  }
}

# Allow the dead-letter policy to publish undeliverable messages to the DLQ topic
resource "google_pubsub_topic_iam_member" "dlq_publisher_project" {
  project = var.project_id
  topic   = google_pubsub_topic.dlq.name
  role    = "roles/pubsub.publisher"
  member  = "serviceAccount:service-${data.google_project.number.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

# Allow the processor SA to acknowledge dead-lettered messages on the DLQ subscription
resource "google_pubsub_subscription_iam_member" "dlq_sub_processor" {
  project      = var.project_id
  subscription = google_pubsub_subscription.dlq.name
  role         = "roles/pubsub.subscriber"
  member       = "serviceAccount:${google_service_account.processor.email}"
}

data "google_project" "current" {
  project_id = var.project_id
}

resource "google_cloud_tasks_queue" "rebuild" {
  name     = local.rebuild_queue_name
  location = var.region
  labels   = local.common_labels

  rate_limits {
    max_concurrent_dispatches = 20
    max_dispatches_per_second  = 10
  }

  retry_config {
    max_attempts       = 10
    max_backoff        = "300s"
    min_backoff        = "10s"
    max_doublings      = 2
  }
}

resource "google_firestore_database" "main" {
  name             = local.firestore_db_name
  type             = "FIRESTORE_NATIVE"
  location_id      = var.region
  delete_protection = false
  labels           = local.common_labels

  cmk_config {
    kms_key_name = google_kms_crypto_key.projection.id
  }
}

# Composite index for the MediaCache entity cache collection/kind
resource "google_firestore_index" "cache" {
  project    = var.project_id
  database   = google_firestore_database.main.name
  collection = "MediaCache"

  fields {
    field_path = "ownerId"
    order      = "ASCENDING"
  }

  fields {
    field_path = "updatedAt"
    order      = "DESCENDING"
  }

  query_scope = "COLLECTION"
}

resource "google_storage_bucket" "audit" {
  name                        = local.audit_bucket_name
  location                    = var.region
  uniform_bucket_level_access = true
  public_access_prevention    = "ENFORCED"
  force_destroy               = true
  labels                      = local.common_labels

  versioning {
    enabled = true
  }

  encryption {
    default_kms_key = google_kms_crypto_key.audit.id
  }

  lifecycle_rule {
    condition {
      age = 365
    }
    action {
      type = "SetStorageClass"
      storage_class = "COLDLINE"
    }
  }
}

resource "google_bigquery_dataset" "audit" {
  dataset_id = local.bq_dataset_id
  location   = var.region
  labels     = local.common_labels

  default_kms_key = google_kms_crypto_key.audit.id
}

resource "google_bigquery_table" "audit_events" {
  dataset_id = google_bigquery_dataset.audit.dataset_id
  table_id   = local.bq_table_id
  labels      = local.common_labels

  schema = jsonencode([
    { name = "eventId", type = "STRING" },
    { name = "eventType", type = "STRING" },
    { name = "aggregateId", type = "STRING" },
    { name = "aggregateVersion", type = "INTEGER" },
    { name = "ownerId", type = "STRING" },
    { name = "occurredAt", type = "TIMESTAMP" },
    { name = "correlationId", type = "STRING" },
    { name = "data", type = "JSON" },
    { name = "batchId", type = "STRING" },
    { name = "ingestedAt", type = "TIMESTAMP" }
  ])
}

resource "google_vpc_access_connector" "main" {
  name          = local.vpc_connector_name
  region        = var.region
  network       = google_compute_network.vpc.id
  ip_cidr_range = "10.30.0.0/28"
  labels        = local.common_labels
}

resource "google_cloud_run_v2_service" "api" {
  name     = local.run_service_name
  location = var.region
  ingress  = "INGRESS_TRAFFIC_ALL"
  labels   = local.common_labels

  template {
    service_account = google_service_account.api.email
    min_instance_count = 2
    max_instance_count = 10

    vpc_access {
      connector = google_vpc_access_connector.main.id
      egress    = "PRIVATE_RANGES_ONLY"
    }

    containers {
      image = var.api_image
      ports {
        container_port = 8080
      }
      resources {
        limits = {
          cpu    = "1000m"
          memory = "512Mi"
        }
      }
      env {
        name  = "DATABASE_URL"
        value_source {
          secret {
            secret = google_secret_manager_secret.db_url.secret_id
            version = "1"
          }
        }
      }
      env {
        name  = "DATASTORE_NAMESPACE"
        value = local.datastore_namespace
      }
      env {
        name  = "FIREBASE_AUTH_JWKS_URL"
        value = "${var.gcp_endpoint_url}/robot/v1/metadata/jwk/securetoken@system.gserviceaccount.com"
      }
      env {
        name  = "GOOGLE_CLOUD_PROJECT"
        value = var.project_id
      }
    }
  }

  depends_on = [
    google_service_networking_connection.psa,
    google_sql_database_instance.main,
    google_secret_manager_secret_version.db_url,
  ]
}

# ---- Processor worker (triggered by Pub/Sub push subscription) ----
resource "google_cloudfunctions2_function" "processor" {
  name        = local.processor_fn_name
  location    = var.region
  description = "MediaPulse projector: consumes media events, updates Firestore, invalidates Datastore cache"
  labels      = local.common_labels

  build_config {
    runtime     = "python311"
    entry_point = "handler"
  }

  service_config {
    service_account_email       = google_service_account.processor.email
    max_instance_count           = 10
    ingress_settings             = "ALLOW_ALL"
    environment_variables = {
      FIRESTORE_DATABASE    = google_firestore_database.main.name
      DATASTORE_NAMESPACE   = local.datastore_namespace
      GOOGLE_CLOUD_PROJECT  = var.project_id
      PROCESSOR_IMAGE       = var.processor_image
    }
  }
}

# ---- Outbox relay worker (invoked on 1-minute schedule) ----
resource "google_cloudfunctions2_function" "relay" {
  name        = local.relay_fn_name
  location    = var.region
  description = "MediaPulse outbox relay: polls Cloud SQL outbox and publishes to Pub/Sub"
  labels      = local.common_labels

  build_config {
    runtime     = "python311"
    entry_point = "handler"
  }

  service_config {
    service_account_email = google_service_account.relay.email
    max_instance_count     = 5
    ingress_settings       = "ALLOW_ALL"
    environment_variables = {
      DATABASE_URL        = local.database_url
      PUBSUB_TOPIC        = google_pubsub_topic.main.name
      GOOGLE_CLOUD_PROJECT = var.project_id
      RELAY_IMAGE         = var.relay_image
    }
  }
}

# ---- Audit archiver worker (invoked every 5 minutes) ----
resource "google_cloudfunctions2_function" "archiver" {
  name        = local.archiver_fn_name
  location    = var.region
  description = "MediaPulse audit archiver: writes NDJSON audit batches to GCS and BigQuery"
  labels      = local.common_labels

  build_config {
    runtime     = "python311"
    entry_point = "handler"
  }

  service_config {
    service_account_email = google_service_account.archiver.email
    max_instance_count     = 5
    ingress_settings       = "ALLOW_ALL"
    environment_variables = {
      DATABASE_URL        = local.database_url
      GCS_BUCKET           = google_storage_bucket.audit.name
      GOOGLE_CLOUD_PROJECT = var.project_id
      ARCHIVER_IMAGE       = var.archiver_image
    }
  }
}

resource "google_cloud_scheduler_job" "relay" {
  name     = local.relay_job_name
  region   = var.region
  schedule = "* * * * *"
  time_zone = "Etc/UTC"
  labels   = local.common_labels

  http_target {
    http_method = "POST"
    uri         = google_cloudfunctions2_function.relay.service_config[0].uri

    oidc_token {
      service_account_email = google_service_account.scheduler.email
      audience              = google_cloudfunctions2_function.relay.service_config[0].uri
    }
  }

  attempt_deadline = "320s"
}

resource "google_cloud_scheduler_job" "archiver" {
  name     = local.archiver_job_name
  region   = var.region
  schedule = "*/5 * * * *"
  time_zone = "Etc/UTC"
  labels   = local.common_labels

  http_target {
    http_method = "POST"
    uri         = google_cloudfunctions2_function.archiver.service_config[0].uri

    oidc_token {
      service_account_email = google_service_account.scheduler.email
      audience              = google_cloudfunctions2_function.archiver.service_config[0].uri
    }
  }

  attempt_deadline = "320s"
}

